// Code node: "Rank Customers" (JavaScript, mode: Run Once for All Items)
// Input: one item per customer from the Summarize node, for example
//   { customer: 'Asha Traders', sum_amount: 2000, count_order_id: 4 }
// Output: the same customers, rounded, ranked, with a percentage share.

// All items from the previous node (Total per Customer)
const groups = $input.all();

// Reference an EARLIER node by name: how many order items went in
const orderCount = $('Clean Fields').all().length;

// Total value of all orders, used for the share percentage
const grandTotal = groups.reduce((sum, g) => sum + g.json.sum_amount, 0);

const round2 = (n) => Math.round(n * 100) / 100;

// Every returned item must be an object with a json key
const rows = groups.map((g) => ({
  json: {
    customer: g.json.customer,
    orders: g.json.count_order_id,
    total: round2(g.json.sum_amount),
    share_pct: Math.round((g.json.sum_amount / grandTotal) * 1000) / 10,
    all_orders: orderCount,
  },
}));

// Highest spender first
rows.sort((a, b) => b.json.total - a.json.total);

return rows;

