// Mock version of the course's ABCorp data warehouse API. It has no dependencies.
// GET /orders returns a JSON array. n8n turns each array element into one item.
const http = require('node:http');

const PORT = Number(process.env.PORT || 3000);
const API_KEY = process.env.ORDERS_API_KEY; // must match the n8n Header Auth credential

const orders = [
  { orderID: 1001, customerID: 501, employeeName: 'Asha Rao', orderPrice: 1200, orderStatus: 'processing' },
  { orderID: 1002, customerID: 502, employeeName: 'Vikram Singh', orderPrice: 850, orderStatus: 'booked' },
  { orderID: 1003, customerID: 503, employeeName: 'Meera Iyer', orderPrice: 430, orderStatus: 'processing' },
  { orderID: 1004, customerID: 504, employeeName: 'Rahul Das', orderPrice: 2100, orderStatus: 'booked' },
  { orderID: 1005, customerID: 505, employeeName: 'Asha Rao', orderPrice: 660, orderStatus: 'booked' }
];

function send(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(body));
}

http.createServer((req, res) => {
  // Header auth: the client must send 'unique-id: <key>'. Node lower-cases header names.
  if (req.headers['unique-id'] !== API_KEY) {
    return send(res, 401, { error: 'Missing or wrong unique-id header' });
  }
  if (req.method === 'GET' && req.url === '/orders') {
    return send(res, 200, orders); // top-level array, so n8n creates 5 items
  }
  send(res, 404, { error: 'Not found' });
}).listen(PORT, () => console.log(`mock-api listening on :${PORT}`));

