// Minimal alert sink. In real work, swap this for Slack, Teams, email or PagerDuty.
const http = require('http');
const PORT = process.env.PORT || 4000;

http
  .createServer((req, res) => {
    if (req.method === 'POST' && req.url === '/alert') {
      let body = '';
      req.on('data', (chunk) => (body += chunk));
      req.on('end', () => {
        try {
          const alert = JSON.parse(body);
          // One clear line per failure: workflow, failing node, message, link
          console.log(`[ALERT] ${new Date().toISOString()} ${alert.text}`);
          console.log(`        failingNode=${alert.failingNode} url=${alert.executionUrl}`);
        } catch (err) {
          console.log('[ALERT] could not parse body:', body);
        }
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end('{"received":true}');
      });
      return;
    }
    res.writeHead(404);
    res.end();
  })
  .listen(PORT, () => console.log(`alert-receiver listening on :${PORT}`));

